import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.D3sJ1xc1.js";const d=JSON.parse('{"title":"📜 Regulament Roleplay (Română)","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-general.md","filePath":"regulament-general.md"}'),t={name:"regulament-general.md"};function u(n,e,o,c,s,p){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="📜-regulament-roleplay-romana" tabindex="-1">📜 Regulament Roleplay (Română) <a class="header-anchor" href="#📜-regulament-roleplay-romana" aria-label="Permalink to &quot;📜 Regulament Roleplay (Română)&quot;">​</a></h1><hr><h2 id="cap-1-introducere" tabindex="-1">CAP. 1 - INTRODUCERE <a class="header-anchor" href="#cap-1-introducere" aria-label="Permalink to &quot;CAP. 1 - INTRODUCERE&quot;">​</a></h2><h2 id="_1-1-dispozitii-generale" tabindex="-1">1.1 Dispoziții generale <a class="header-anchor" href="#_1-1-dispozitii-generale" aria-label="Permalink to &quot;1.1 Dispoziții generale&quot;">​</a></h2><p>Participarea pe serverul <strong>LEGACY OF CLT</strong> implică acceptarea și respectarea în totalitate a prezentului regulament.</p><ul><li>Necunoașterea regulamentului nu reprezintă o scuză și nu înlătură aplicarea sancțiunilor.</li><li>Pentru orice reclamație sau ticket bazat pe o acțiune Roleplay este obligatorie prezentarea unei dovezi clare și complete.</li><li>Dovada trebuie să conțină întreaga desfășurare a acțiunii și identificarea persoanei reclamate.</li><li>În lipsa unei dovezi concludente, administrația își rezervă dreptul de a respinge sesizarea.</li><li>În cazul încălcării regulamentului în cadrul activităților ilegale, bunurile obținute sau utilizate în mod necorespunzător pot fi confiscate în funcție de gravitatea faptei.</li></ul><hr><h2 id="cap-2-notiuni-de-baza-roleplay" tabindex="-1">CAP. 2 - NOȚIUNI DE BAZĂ ROLEPLAY <a class="header-anchor" href="#cap-2-notiuni-de-baza-roleplay" aria-label="Permalink to &quot;CAP. 2 - NOȚIUNI DE BAZĂ ROLEPLAY&quot;">​</a></h2><h2 id="_2-1-ce-este-roleplay-ul-rp" tabindex="-1">2.1 Ce este Roleplay-ul (RP) <a class="header-anchor" href="#_2-1-ce-este-roleplay-ul-rp" aria-label="Permalink to &quot;2.1 Ce este Roleplay-ul (RP)&quot;">​</a></h2><p>Roleplay-ul (RP) reprezintă simularea unei vieți cât mai apropiate de realitate într-un mediu virtual.</p><p>Fiecare jucător își creează un personaj și trebuie să acționeze conform personalității, experienței și limitărilor acestuia.</p><p>Scopul principal al serverului <strong>LEGACY OF CLT</strong> este dezvoltarea unor povești credibile și a unor interacțiuni de calitate între jucători.</p><hr><h2 id="_2-2-in-character-ic" tabindex="-1">2.2 In Character (IC) <a class="header-anchor" href="#_2-2-in-character-ic" aria-label="Permalink to &quot;2.2 In Character (IC)&quot;">​</a></h2><p>Termenul <strong>In Character (IC)</strong> se referă la toate acțiunile, deciziile și reacțiile realizate din perspectiva personajului pe care îl interpretezi.</p><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Acționează exact cum ar face personajul tău într-o situație reală.</li><li>Nu folosi informații pe care personajul tău nu le-ar putea cunoaște.</li></ul><h3 id="exemplu" tabindex="-1">Exemplu <a class="header-anchor" href="#exemplu" aria-label="Permalink to &quot;Exemplu&quot;">​</a></h3><p>Dacă personajul tău este mecanic, acesta nu poate cunoaște informații despre activități mafiote doar pentru că tu, ca jucător, le cunoști.</p><hr><h2 id="_2-3-out-of-character-ooc" tabindex="-1">2.3 Out Of Character (OOC) <a class="header-anchor" href="#_2-3-out-of-character-ooc" aria-label="Permalink to &quot;2.3 Out Of Character (OOC)&quot;">​</a></h2><p>Out Of Character (OOC) reprezintă orice comunicare realizată în afara contextului Roleplay.</p><h3 id="sunt-considerate-ooc" tabindex="-1">Sunt considerate OOC <a class="header-anchor" href="#sunt-considerate-ooc" aria-label="Permalink to &quot;Sunt considerate OOC&quot;">​</a></h3><ul><li>Report-urile.</li><li>Ticket-ele.</li><li>Discuțiile administrative.</li><li>Conversațiile cu membrii Staff.</li></ul><p>Informațiile obținute prin canale OOC nu pot fi folosite în acțiuni Roleplay.</p><hr><h2 id="cap-3-reguli-generale-roleplay" tabindex="-1">CAP. 3 - REGULI GENERALE ROLEPLAY <a class="header-anchor" href="#cap-3-reguli-generale-roleplay" aria-label="Permalink to &quot;CAP. 3 - REGULI GENERALE ROLEPLAY&quot;">​</a></h2><h2 id="_3-1-jaf-sub-50-ore" tabindex="-1">3.1 Jaf sub 50 ore <a class="header-anchor" href="#_3-1-jaf-sub-50-ore" aria-label="Permalink to &quot;3.1 Jaf sub 50 ore&quot;">​</a></h2><p>Jucătorii aflați la început beneficiază de protecție pentru a învăța mecanicile serverului.</p><h3 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzisă jefuirea jucătorilor cu mai puțin de 50 de ore.</li><li>Este interzisă răpirea jucătorilor cu mai puțin de 50 de ore.</li><li>Aceștia nu pot participa activ la activități ilegale complexe.</li></ul><p>Încălcarea acestei reguli va fi sancționată sever.</p><hr><h2 id="_3-2-combat-log-cl" tabindex="-1">3.2 Combat Log (CL) <a class="header-anchor" href="#_3-2-combat-log-cl" aria-label="Permalink to &quot;3.2 Combat Log (CL)&quot;">​</a></h2><p>Părăsirea jocului în timpul unei acțiuni Roleplay este considerată abatere gravă.</p><h3 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Jucătorul trebuie să revină în cel mai scurt timp posibil.</li><li>Absența fără justificare poate duce la sancțiuni.</li><li>Disconnect-ul intenționat pentru evitarea RP-ului este strict interzis.</li></ul><hr><h2 id="_3-3-cop-bait-cb" tabindex="-1">3.3 Cop Bait (CB) <a class="header-anchor" href="#_3-3-cop-bait-cb" aria-label="Permalink to &quot;3.3 Cop Bait (CB)&quot;">​</a></h2><p>Cop Bait reprezintă provocarea intenționată a Poliției fără un motiv Roleplay.</p><h3 id="exemple" tabindex="-1">Exemple <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple&quot;">​</a></h3><ul><li>Atragi Poliția doar pentru urmăriri inutile.</li><li>Provoci intervenții prin comportament abuziv în trafic.</li><li>Creezi conflicte artificiale fără un scop Roleplay.</li></ul><hr><h2 id="_3-4-inselatorii-scam-fraud" tabindex="-1">3.4 Înșelătorii (Scam / Fraud) <a class="header-anchor" href="#_3-4-inselatorii-scam-fraud" aria-label="Permalink to &quot;3.4 Înșelătorii (Scam / Fraud)&quot;">​</a></h2><p>Orice formă de înșelătorie este strict interzisă.</p><h3 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Tranzacțiile trebuie realizate în mod corect.</li><li>Abuzul de încredere este sancționat.</li><li>Manipularea altor jucători pentru bani sau bunuri este interzisă.</li></ul><hr><h2 id="_3-5-jafuri-magazine-banci" tabindex="-1">3.5 Jafuri Magazine / Bănci <a class="header-anchor" href="#_3-5-jafuri-magazine-banci" aria-label="Permalink to &quot;3.5 Jafuri Magazine / Bănci&quot;">​</a></h2><p>Acțiunile asupra magazinelor și băncilor trebuie să respecte regulamentul.</p><h3 id="reguli-4" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-4" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este necesar numărul minim de participanți.</li><li>Este interzisă blocarea intenționată a accesului.</li><li>Ostaticii nu pot fi abuzați.</li><li>Nu poți repeta același jaf cu aceleași persoane.</li></ul><hr><h2 id="_3-6-joburi-si-activitati-legale" tabindex="-1">3.6 Joburi și activități legale <a class="header-anchor" href="#_3-6-joburi-si-activitati-legale" aria-label="Permalink to &quot;3.6 Joburi și activități legale&quot;">​</a></h2><p>Joburile legale trebuie utilizate doar în scopul pentru care au fost create.</p><h3 id="reguli-5" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-5" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzisă folosirea joburilor legale pentru activități ilegale.</li><li>Roleplay-ul trebuie să fie coerent cu natura jobului.</li><li>Abuzul funcției pentru avantaje personale este sancționat.</li></ul><hr><h2 id="_3-7-refuz-roleplay" tabindex="-1">3.7 Refuz Roleplay <a class="header-anchor" href="#_3-7-refuz-roleplay" aria-label="Permalink to &quot;3.7 Refuz Roleplay&quot;">​</a></h2><p>Refuzul de a participa la o acțiune Roleplay validă este interzis.</p><h3 id="reguli-6" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-6" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Jucătorii trebuie să răspundă situațiilor RP.</li><li>Ignorarea interacțiunilor reprezintă abatere.</li><li>Dacă mori și în jurul tău există o acțiune RP, ai voie să îți dai respawn doar dacă ai opțiunea activă.</li></ul><hr><h2 id="_3-8-trolling" tabindex="-1">3.8 Trolling <a class="header-anchor" href="#_3-8-trolling" aria-label="Permalink to &quot;3.8 Trolling&quot;">​</a></h2><p>Comportamentul care afectează experiența altor jucători este interzis.</p><h3 id="exemple-1" tabindex="-1">Exemple <a class="header-anchor" href="#exemple-1" aria-label="Permalink to &quot;Exemple&quot;">​</a></h3><ul><li>Earrape.</li><li>Comportament haotic fără sens Roleplay.</li><li>Distrugerea intenționată a atmosferei serverului.</li></ul><hr><h2 id="_3-9-fake-cop" tabindex="-1">3.9 Fake Cop <a class="header-anchor" href="#_3-9-fake-cop" aria-label="Permalink to &quot;3.9 Fake Cop&quot;">​</a></h2><p>Este interzisă impersonarea autorităților.</p><h3 id="reguli-7" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-7" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Nu ai voie să pretinzi că faci parte din Poliție.</li><li>Nu ai voie să pretinzi că faci parte din Serviciile Medicale.</li><li>Nu poți utiliza un statut fals pentru a influența alți jucători.</li></ul><hr><h2 id="_3-10-afk-in-roleplay" tabindex="-1">3.10 AFK în Roleplay <a class="header-anchor" href="#_3-10-afk-in-roleplay" aria-label="Permalink to &quot;3.10 AFK în Roleplay&quot;">​</a></h2><p>Este interzis să fii AFK în timpul unei acțiuni Roleplay.</p><h2 id="reguli-8" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-8" aria-label="Permalink to &quot;Reguli&quot;">​</a></h2><ul><li>Nu ai voie să părăsești jocul în timpul unei acțiuni RP.</li><li>Nu ai voie să ignori participanții la acțiune.</li><li>Lipsa de reacție afectează desfășurarea Roleplay-ului și poate fi sancționată.</li></ul><hr><h2 id="_3-11-deschidere-ooc-in-ic" tabindex="-1">3.11 Deschidere OOC în IC <a class="header-anchor" href="#_3-11-deschidere-ooc-in-ic" aria-label="Permalink to &quot;3.11 Deschidere OOC în IC&quot;">​</a></h2><p>Este interzisă aducerea discuțiilor OOC în timpul unei acțiuni Roleplay.</p><h3 id="reguli-9" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-9" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Nu ai voie să vorbești despre report-uri sau ticket-e în IC.</li><li>Amenințările cu Staff-ul sunt strict interzise.</li><li>Discuțiile administrative trebuie purtate exclusiv în canalele OOC.</li></ul><hr><h2 id="cap-4-dispozitii-finale" tabindex="-1">CAP. 4 - DISPOZIȚII FINALE <a class="header-anchor" href="#cap-4-dispozitii-finale" aria-label="Permalink to &quot;CAP. 4 - DISPOZIȚII FINALE&quot;">​</a></h2><h2 id="_4-1-aplicarea-regulamentului" tabindex="-1">4.1 Aplicarea regulamentului <a class="header-anchor" href="#_4-1-aplicarea-regulamentului" aria-label="Permalink to &quot;4.1 Aplicarea regulamentului&quot;">​</a></h2><p>Administrația serverului își rezervă dreptul de a aplica sancțiuni în funcție de gravitatea fiecărei situații.</p><p>Fiecare jucător este responsabil de respectarea regulamentului și de menținerea unui mediu Roleplay de calitate pe serverul <strong>LEGACY OF CLT</strong>.</p>',87)])])}const m=a(t,[["render",u]]);export{d as __pageData,m as default};
